+/**
+ * @brief 返回 s 的 UTF-8 前缀长度：不超过 max_bytes，且不切断多字节字符。
+ */
+static size_t bicycle_ui_ctl_utf8_prefix(const char * s, size_t max_bytes)
+{
+    size_t n = 0u;
+
+    while (s != NULL && s[n] != '\0' && n < max_bytes) {
+        const unsigned char c = (unsigned char)s[n];
+        size_t len = 1u;
+
+        if ((c & 0xE0u) == 0xC0u) {
+            len = 2u;
+        } else if ((c & 0xF0u) == 0xE0u) {
+            len = 3u;
+        } else if ((c & 0xF8u) == 0xF0u) {
+            len = 4u;
+        }
+        if (n + len > max_bytes) {
+            break;
+        }
+        n += len;
+    }
+
+    return n;
+}
